  FT["PH-H6349"] = {"id":"PH-H6349","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7869_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在八打雁市伊斯拉贝尔德的San Agapito描笼涯设立中学，名称为San Agapito中学，并为此拨款的法案","en":"An Act Establishing a High School in Barangay San Agapito, Isla Verde, Batangas City, to Be Known as the San Agapito High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in Barangay San Agapito, Isla Verde, Batangas City, to Be Known as the San Agapito High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7869","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-01-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7869_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6349-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in Barangay San Agapito, Isla Verde, Batangas City, to be known as the San Agapito High School."}},{"id":"PH-H6349-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"the Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6349-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"the amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6349-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p90","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a High School in Barangay San Agapito, Isla Verde, Batangas City, to Be Known as the San Agapito High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6350"] = {"id":"PH-H6350","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7870_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Brooke's Point市","en":"An Act Establishing a National High School in the Municipality of Brooke's Point, Province of Palawan, to Be Known as the Brooke's Point National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the Municipality of Brooke's Point, Province of Palawan, to Be Known as the Brooke's Point National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7870","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-01-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7870_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6350-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a national high school in the Municipality of Brooke's Point, Province of Palawan, with school site at Barangay Pangobilian, to be known as the Brooke's Point National High School."}},{"id":"PH-H6350-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"the Secretary of Education, Culture and Sports shall issue the necessary rules, orders and circulars to implement the provisions of this Act."}},{"id":"PH-H6350-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"the amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6350-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApprove,"}}],"pack":"ph-p90"};
